'use strict';

/**
 * PhishingClassifier
 *
 * Runs in two modes:
 *   'rf'        — full Random Forest loaded from model.json
 *   'heuristic' — tuned rule-based fallback (no model.json needed)
 *
 * model.json is generated by running: python train_export.py
 */
class PhishingClassifier {

  constructor() {
    this.model  = null;
    this.mode   = 'heuristic';   // upgraded to 'rf' when model.json loads
    this._ready = false;
  }

  // ── Model loading ──────────────────────────────────────────────────────────

  /**
   * Attempt to load model.json.
   * Silently falls back to heuristic mode on any failure.
   * @returns {Promise<boolean>} true if RF model loaded successfully
   */
  async loadModel(url = './model.json') {
    try {
      const res = await fetch(url, { cache: 'force-cache' });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const data = await res.json();

      // Validate basic structure
      if (!data.trees || !Array.isArray(data.trees) || !data.features) {
        throw new Error('Invalid model.json structure');
      }

      this.model = data;
      this.mode  = 'rf';
      console.info(
        `[PhishGuard] ML model loaded — ${data.n_estimators} trees, ` +
        `${data.features.length} features`
      );
      this._ready = true;
      return true;
    } catch (err) {
      console.info(
        `[PhishGuard] model.json not found or invalid — using heuristic mode. ` +
        `(Run train_export.py to enable ML mode.)`
      );
      this.mode   = 'heuristic';
      this._ready = true;
      return false;
    }
  }

  // ── Random Forest inference ────────────────────────────────────────────────

  /**
   * Walk a single decision tree and return P(phishing).
   * @param {object} tree  — exported tree structure
   * @param {number[]} X   — feature vector aligned to model.features order
   * @returns {number}
   */
  _traverseTree(tree, X) {
    let node = 0;
    const LEAF = -1;

    while (tree.children_left[node] !== LEAF) {
      const fi        = tree.feature[node];
      const threshold = tree.threshold[node];

      node = (X[fi] <= threshold)
        ? tree.children_left[node]
        : tree.children_right[node];
    }

    // value[node] = [n_legitimate, n_phishing]
    const val   = tree.value[node];
    const nLeg  = val[0];
    const nPhi  = val[1];
    return nPhi / (nLeg + nPhi + 1e-10);
  }

  /**
   * Run all trees and average their probabilities.
   * @param {number[]} featureArray — feature values in extraction order
   * @param {string[]} names        — feature names in extraction order
   * @returns {number} P(phishing) ∈ [0, 1]
   */
  _predictRF(featureArray, names) {
    // Build an index from feature name → position in featureArray
    const nameToIdx = Object.create(null);
    names.forEach((name, i) => { nameToIdx[name] = i; });

    // Reorder to match the model's feature order
    const X = this.model.features.map(name => {
      const idx = nameToIdx[name];
      return (idx !== undefined) ? featureArray[idx] : 0;
    });

    // Average probability across all trees
    let sum = 0;
    for (const tree of this.model.trees) {
      sum += this._traverseTree(tree, X);
    }
    return sum / this.model.trees.length;
  }

  // ── Heuristic fallback ────────────────────────────────────────────────────

  /**
   * Compound-signal heuristic classifier.
   *
   * Design principle: brand names (paypal, amazon) legitimately appear in
   * real domains, so a single keyword hit must NOT be treated as a strong
   * signal in isolation. Each soft signal is added to `prob` incrementally;
   * hard indicators (IP host, @ symbol) floor the probability immediately.
   * Combined signals (keyword + bad TLD, keyword + no HTTPS) are scored
   * higher than either signal alone.
   *
   * @param {object} features — feature name → value map
   * @returns {number} estimated P(phishing) ∈ [0.01, 0.99]
   */
  _predictHeuristic(features) {
    let prob = 0.0;

    const kw      = features.suspicious_keyword === 1;
    const badTld  = features.suspicious_tld     === 1;
    const noHttps = features.uses_https         === 0;
    const longUrl = features.url_length          > 75;
    const highEnt = features.url_entropy         > 4.5;
    const short   = features.is_shortened_url   === 1;

    // ── Absolute / near-certain phishing signals ─────────────────────────
    // These alone are strong enough to push above 0.65 regardless of other features.
    if (features.has_ip_address  === 1) prob = Math.max(prob, 0.88);
    if (features.has_at_symbol   === 1) prob = Math.max(prob, 0.90);
    if (features.has_double_slash === 1) prob = Math.max(prob, 0.78);

    // ── Compound signals (require ≥2 co-occurring features) ──────────────
    // A keyword on a suspicious TLD is a very strong signal (e.g. paypal.tk)
    if (kw && badTld)             prob = Math.max(prob, 0.88);
    // Keyword + no HTTPS: legitimate login pages always use HTTPS
    if (kw && noHttps)            prob += 0.38;
    // Keyword + long URL: padding the URL to confuse users
    if (kw && longUrl)            prob += 0.18;
    // Keyword + high entropy: obfuscated phishing path
    if (kw && highEnt)            prob += 0.16;
    // Shortener + keyword: hiding destination behind a redirect
    if (short && kw)              prob += 0.22;
    // Shortener + no HTTPS
    if (short && noHttps)         prob += 0.12;
    // Bad TLD + no HTTPS + long URL: classic free-hosting phishing pattern
    if (badTld && noHttps && longUrl) prob += 0.20;

    // ── Standalone soft signals ───────────────────────────────────────────
    // These contribute meaningfully on their own but rarely push above 0.65
    // in isolation, preventing false positives on legitimate domains.
    if (badTld)                           prob += 0.14;
    if (features.url_entropy > 4.9)       prob += 0.22;
    else if (features.url_entropy > 4.5)  prob += 0.10;
    if (features.url_length > 100)        prob += 0.13;
    else if (features.url_length > 75)    prob += 0.07;
    if (features.subdomain_count > 3)     prob += 0.14;
    if (features.subdomain_count > 1 && badTld) prob += 0.15;
    if (short)                            prob += 0.18;
    if (features.digit_letter_ratio > 0.4) prob += 0.10;
    if (features.num_hyphens > 5)         prob += 0.09;
    if (features.has_port === 1)          prob += 0.09;
    if (features.num_percent > 4)         prob += 0.06;
    if (noHttps)                          prob += 0.03;

    return Math.min(0.99, Math.max(0.01, prob));
  }

  // ── Public API ────────────────────────────────────────────────────────────

  /**
   * Classify a URL from its extracted features.
   *
   * @param {{
   *   features: Object.<string,number>,
   *   featureArray: number[],
   *   names: string[]
   * }} extracted — output of extractFeatures()
   *
   * @returns {{
   *   probability: number,   P(phishing) ∈ [0,1]
   *   label: 'phishing'|'legitimate'|'suspicious',
   *   confidenceLabel: string,
   *   confidenceLevel: 'very-high'|'high'|'medium'|'low',
   *   mode: string
   * }}
   */
  predict(extracted) {
    const { features, featureArray, names } = extracted;

    let probability;
    if (this.mode === 'rf' && this.model) {
      probability = this._predictRF(featureArray, names);
    } else {
      probability = this._predictHeuristic(features);
    }

    // Clamp to [0, 1]
    probability = Math.max(0, Math.min(1, probability));

    // Label
    let label;
    if (probability >= 0.65)      label = 'phishing';
    else if (probability <= 0.35) label = 'legitimate';
    else                          label = 'suspicious';

    // Confidence (how far from the 0.5 decision boundary)
    const dist = Math.abs(probability - 0.5);
    let confidenceLevel, confidenceLabel;
    if      (dist >= 0.40) { confidenceLevel = 'very-high'; confidenceLabel = 'Very High'; }
    else if (dist >= 0.28) { confidenceLevel = 'high';      confidenceLabel = 'High';      }
    else if (dist >= 0.14) { confidenceLevel = 'medium';    confidenceLabel = 'Medium';    }
    else                   { confidenceLevel = 'low';       confidenceLabel = 'Low';       }

    return { probability, label, confidenceLevel, confidenceLabel, mode: this.mode };
  }
}
